def buildOption(text, value, bgColor):

	unselectedWashedBgColor = 'color-mix(in srgb, var(%s) 30%%, white)'%bgColor
	selectedWashedBgColor = 'color-mix(in srgb, var(%s) 60%%, white)'%bgColor
	return {
			"text": text,
			"value": value,
			"unselectedStyle": {"classes": "", "backgroundColor": unselectedWashedBgColor, 'color': '--kcGray-40'},
			"selectedStyle": {"classes": "", "backgroundColor": selectedWashedBgColor, 'color': system.kanoa.utilities.getContrastingColor(bgColor), 'box-shadow': '0 10px 25px rgba(0, 0, 0, 0.15),   0 4px 10px rgba(0, 0, 0, 0.08)'}
		}

options = []
for k,v in value.items():
	options.append(buildOption(v['maintenanceTypeName'], v['maintenanceTypeId'], v['maintenanceTypeColor']))

return options

